// Generated from the user-supplied QIP 2005 Clients/clients.cfg (qipim.cz MOD catalog).
// Original config credits: volkov.volkov, Lms; collaboration: panther7.
// Recognition-only: never modify transmitted OSCAR capabilities or X-status GUIDs.
// Only capability-only records with sufficiently distinctive signatures are imported.
#pragma once
#include <stddef.h>
#include <string.h>
#include <string>

struct KicqCatalogRule { const char *name; const char *caps; const char *noCaps; bool exact; };

static int KicqCatalogHexNibble(char c)
{
 if (c >= '0' && c <= '9') return c - '0';
 if (c >= 'A' && c <= 'F') return c - 'A' + 10;
 if (c >= 'a' && c <= 'f') return c - 'a' + 10;
 return -1;
}

// A signature is matched only at the START of a 16-byte OSCAR capability,
// never as an arbitrary substring in a packet or in an X-status description.
static bool KicqCatalogHasCap(const unsigned char *data, size_t len, const char *hex, size_t nhex)
{
 if (nhex < 8 || (nhex & 1) || nhex > 32) return false;
 if (!data || len < 16) return false;
 for (size_t off = 0; off + 16 <= len; off += 16) {
  bool same = true;
  for (size_t i = 0; i < nhex; i += 2) {
   const int a = KicqCatalogHexNibble(hex[i]);
   const int b = KicqCatalogHexNibble(hex[i+1]);
   if (a < 0 || b < 0 || data[off+i/2] != (unsigned char)((a<<4)|b)) { same=false; break; }
  }
  if (same) return true;
 }
 return false;
}

static bool KicqCatalogMatchesAll(const unsigned char *data, size_t len, const char *tokens)
{
 const char *p = tokens;
 while (p && *p) {
  const char *end = strchr(p, '|');
  size_t n = end ? size_t(end-p) : strlen(p);
  if (!KicqCatalogHasCap(data,len,p,n)) return false;
  if (!end) break;
  p = end + 1;
 }
 return true;
}
static bool KicqCatalogMatchesNone(const unsigned char *data, size_t len, const char *tokens)
{
 const char *p = tokens;
 while (p && *p) {
  const char *end = strchr(p, '|');
  size_t n = end ? size_t(end-p) : strlen(p);
  if (KicqCatalogHasCap(data,len,p,n)) return false;
  if (!end) break;
  p = end + 1;
 }
 return true;
}

